@ExtendWith(MockitoExtension.class)
class FavouriteServiceImplTest {

    @Mock
    private FavouriteRepository favouriteRepository;

    @Mock
    private RestTemplate restTemplate;

    @InjectMocks
    private FavouriteServiceImpl favouriteService;

    // GreyTest trace: findAll | Ánh xạ, bổ sung thông tin, loại trùng và trả danh sách bất biến | BR-003 -> TP-003 -> TC-1400
    @Test
    void findAll_enrichesDeduplicatesAndReturnsImmutableList() {
        LocalDateTime likeDate = LocalDateTime.of(2025, 3, 8, 10, 15, 30);
        Favourite first = Favourite.builder().userId(11).productId(22).likeDate(likeDate).build();
        Favourite second = Favourite.builder().userId(11).productId(22).likeDate(likeDate).build();
        UserDto user = UserDto.builder().userId(11).build();
        ProductDto product = ProductDto.builder().productId(22).build();
        String userUrl = AppConstant.DiscoveredDomainsApi.USER_SERVICE_API_URL + "/11";
        String productUrl = AppConstant.DiscoveredDomainsApi.PRODUCT_SERVICE_API_URL + "/22";
        when(favouriteRepository.findAll()).thenReturn(Arrays.asList(first, second));
        when(restTemplate.getForObject(userUrl, UserDto.class)).thenReturn(user);
        when(restTemplate.getForObject(productUrl, ProductDto.class)).thenReturn(product);

        List<FavouriteDto> result = favouriteService.findAll();

        assertEquals(1, result.size());
        FavouriteDto dto = result.get(0);
        assertEquals(Integer.valueOf(11), dto.getUserId());
        assertEquals(Integer.valueOf(22), dto.getProductId());
        assertEquals(likeDate, dto.getLikeDate());
        assertEquals(Integer.valueOf(11), dto.getUserDto().getUserId());
        assertEquals(Integer.valueOf(22), dto.getProductDto().getProductId());
